  1	package hotel.messages;
  2	
  3	import java.util.ArrayList;
  4	import java.util.List;
  5	
  6	/** Processes messages through a chain of handlers. */
  7	public final class MessageProcessor {
  8	
  9	    private final List<MessageHandler> handlers;
 10	
 11	    public MessageProcessor(List<MessageHandler> handlers) {
 12	        this.handlers = List.copyOf(handlers);
 13	    }
 14	
 15	    public List<ProcessedMessage.MessageToStore> process(OutgoingMessage message) {
 16	        OutgoingMessage current = message;
 17	        List<ProcessedMessage.MessageToStore> additionalMessages = new ArrayList<>();
 18	        boolean blocked = false;
 19	
 20	        for (MessageHandler handler : handlers) {
 21	            if (blocked) {
 22	                break;
 23	            }
 24	
 25	            ProcessedMessage result = handler.handle(current);
 26	
 27	            if (result.messages().get(0).status() == MessageStatus.BLOCKED) {
 28	                blocked = true;
 29	                additionalMessages.clear();
 30	                additionalMessages.add(result.messages().get(0));
 31	            } else {
 32	                current = new OutgoingMessage(
 33	                    result.messages().get(0).to(),
 34	                    result.messages().get(0).subject(),
 35	                    result.messages().get(0).body()
 36	                );
 37	
 38	                if (result.messages().size() > 1) {
 39	                    additionalMessages.addAll(result.messages().subList(1, result.messages().size()));
 40	                }
 41	            }
 42	        }
 43	
 44	        if (blocked) {
 45	            return additionalMessages;
 46	        }
 47	
 48	        List<ProcessedMessage.MessageToStore> allMessages = new ArrayList<>();
 49	        allMessages.add(new ProcessedMessage.MessageToStore(
 50	            current.to(), current.subject(), current.body(), MessageStatus.SENT
 51	        ));
 52	        allMessages.addAll(additionalMessages);
 53	        return allMessages;
 54	    }
 55	}
 56	package hotel.messages;
 57	
 58	import java.util.List;
 59	
 60	/** The result of processing a message through handlers. */
 61	public record ProcessedMessage(List<MessageToStore> messages) {
 62	
 63	    public static ProcessedMessage sent(String to, String subject, String body) {
 64	        return new ProcessedMessage(List.of(new MessageToStore(to, subject, body, MessageStatus.SENT)));
 65	    }
 66	
 67	    public static ProcessedMessage blocked(String to) {
 68	        return new ProcessedMessage(List.of(new MessageToStore(to, "", "", MessageStatus.BLOCKED)));
 69	    }
 70	
 71	    public static ProcessedMessage multiple(List<MessageToStore> messages) {
 72	        return new ProcessedMessage(messages);
 73	    }
 74	
 75	    public record MessageToStore(String to, String subject, String body, MessageStatus status) {}
 76	}
 77	package hotel.messages;
 78	
 79	import java.util.List;
 80	
 81	/** Sends e-mails to guests. Every e-mail sent is kept in the list of sent messages. */
 82	public final class EmailSender {
 83	
 84	    private final SentMessages sentMessages;
 85	    private final MessageProcessor processor;
 86	
 87	    public EmailSender(SentMessages sentMessages, MessageProcessor processor) {
 88	        this.sentMessages = sentMessages;
 89	        this.processor = processor;
 90	    }
 91	
 92	    public Message send(String to, String subject, String body) {
 93	        OutgoingMessage outgoing = new OutgoingMessage(to, subject, body);
 94	        List<ProcessedMessage.MessageToStore> processed = processor.process(outgoing);
 95	
 96	        Message firstMessage = null;
 97	        for (ProcessedMessage.MessageToStore msg : processed) {
 98	            Message stored = sentMessages.add("EMAIL", msg.to(), msg.subject(), msg.body(), msg.status());
 99	            if (firstMessage == null) {
100	                firstMessage = stored;
101	            }
102	        }
103	
104	        return firstMessage;
105	    }
106	}
